/* ── Print / PDF export ────────────────────────────────────────────────────── */
@media print {
  /* Hide everything that isn't the report content */
  aside,
  nav,
  header,
  [data-topbar],
  [data-sidebar] {
    display: none !important;
  }

  /* Let the report fill the full page width */
  body {
    background: #fff !important;
  }

  /* Unwrap the flex shell so the report flows naturally */
  .flex.h-screen,
  .flex.h-screen > .flex.flex-1.flex-col {
    display: block !important;
    height: auto !important;
    overflow: visible !important;
  }

  main {
    overflow: visible !important;
    padding: 0 !important;
  }

  /* Remove shadows and rounded borders that look odd on paper */
  * {
    box-shadow: none !important;
    print-color-adjust: exact;
    -webkit-print-color-adjust: exact;
  }

  /* Avoid page breaks inside cards */
  .rounded-xl2,
  .rounded-xl {
    break-inside: avoid;
  }

  /* Hide the Export PDF button itself while printing */
  [data-print-hide] {
    display: none !important;
  }
}

