11 | import org.springframework.stereotype.Service;
12 | import org.springframework.transaction.annotation.Transactional;
13 | 
14 | import java.util.List;
15 | 
16 | /**
17 |  * Asynchronous code-review analysis service.
18 |  *
19 |  * <p>Milestone 1 implementation: replaces the previous mock/placeholder
20 |  * pipeline with a genuine deterministic static-analysis engine
21 |  * ({@link StaticAnalysisEngine}).  The engine applies four rule families
22 |  * to the <em>added lines</em> of the submitted unified diff:
23 |  * <ul>
24 |  *   <li>SQLI-001 — SQL injection via string concatenation</li>
25 |  *   <li>CRED-001 — Hardcoded credential literals</li>
26 |  *   <li>EXEC-001 — Dangerous OS command execution</li>
27 |  *   <li>DESER-001 — Unsafe Java deserialization</li>
28 |  * </ul>
29 |  *
30 |  * <p><strong>What this is NOT</strong>: not an AI/LLM model, not a full
31 |  * compiler or parser.  Rules use regex-based pattern matching on individual
32 |  * diff lines and report <em>potential</em> issues, not confirmed
33 |  * vulnerabilities.  See {@code ANALYSIS_ENGINE.md} for limitations.
34 |  *
35 |  * <p>The class name {@code MockAnalysisService} is intentionally retained
36 |  * so that existing Spring wiring and integration-test {@code @Autowired}
37 |  * references continue to resolve without change.
38 |  *
39 |  * <p><strong>Historical data</strong>: findings persisted by previous runs
40 |  * (including the recovered historical review ID 1) are not touched by this
41 |  * service.  The engine only processes reviews that are explicitly submitted
42 |  * or re-triggered.
43 |  */
44 | @Service
45 | public class MockAnalysisService {
46 | 
47 |     private static final Logger log = LoggerFactory.getLogger(MockAnalysisService.class);
48 | 
49 |     private final ReviewRepository   reviewRepository;
50 |     private final FindingRepository  findingRepository;
51 |     private final StaticAnalysisEngine engine;
52 | 
53 |     public MockAnalysisService(ReviewRepository reviewRepository,
54 |                                FindingRepository findingRepository,
55 |                                StaticAnalysisEngine engine) {
56 |         this.reviewRepository = reviewRepository;
57 |         this.findingRepository = findingRepository;
58 |         this.engine = engine;
59 |     }
60 | 
61 |     /**
62 |      * Runs analysis asynchronously so that {@code POST /reviews} returns
63 |      * immediately while analysis proceeds in the background.
64 |      *
65 |      * <p>Steps:
66 |      * <ol>
67 |      *   <li>Mark review ANALYZING (progress 10 %)</li>
68 |      *   <li>Delete any existing findings for this review (idempotent re-run)</li>
69 |      *   <li>Run the static-analysis engine against the stored diff</li>
70 |      *   <li>Persist findings, mark COMPLETED (progress 100 %)</li>
71 |      * </ol>
72 |      *
73 |      * <p>On unexpected error the review is marked FAILED.
74 |      */
75 |     @Async
76 |     @Transactional
77 |     public void analyzeAsync(Long reviewId) {
78 |         log.info("[ANALYSIS] Starting analysis for review {}", reviewId);
79 | 
80 |         Review review = reviewRepository.findById(reviewId).orElse(null);
81 |         if (review == null) {
82 |             log.warn("[ANALYSIS] Review {} not found — skipping", reviewId);
83 |             return;
84 |         }
85 | 
86 |         try {
87 |             // Step 1 — mark ANALYZING
88 |             review.setStatus("ANALYZING");
89 |             review.setProgress(10);
90 |             reviewRepository.save(review);
91 | 
92 |             // Step 2 — clear stale findings (idempotent re-run)
93 |             findingRepository.deleteByReview_Id(reviewId);
94 | 
95 |             // Step 3 — run the engine
96 |             String diff = review.getCodeDiff() == null ? "" : review.getCodeDiff();
97 |             List<Finding> findings = engine.analyze(review, diff);
98 | 
99 |             // Step 4 — progress update
100 |             review.setProgress(70);
101 |             reviewRepository.save(review);
102 | 
103 |             // Step 5 — persist findings
104 |             findingRepository.saveAll(findings);
105 | 
106 |             // Step 6 — mark COMPLETED
107 |             review.setStatus("COMPLETED");
108 |             review.setProgress(100);
109 |             reviewRepository.save(review);
110 | 
111 |             log.info("[ANALYSIS] Completed review {} — {} findings (rules: {})",
112 |                     reviewId, findings.size(), engine.registeredRuleIds());
113 | 
114 |         } catch (Exception ex) {
115 |             log.error("[ANALYSIS] Analysis failed for review {}: {}", reviewId, ex.getMessage(), ex);
116 |             try {
117 |                 review.setStatus("FAILED");
118 |                 reviewRepository.save(review);
119 |             } catch (Exception saveEx) {
120 |                 log.error("[ANALYSIS] Could not persist FAILED status for review {}", reviewId, saveEx);
121 |             }
122 |         }
123 |     }
124 | }
