101 |             String diff = review.getCodeDiff() == null ? "" : review.getCodeDiff();
102 |             List<Finding> findings = engine.analyze(review, diff);
103 | 
104 |             // Step 4 — progress update
105 |             review.setProgress(70);
106 |             reviewRepository.save(review);
107 | 
108 |             // Step 5 — persist findings
109 |             findingRepository.saveAll(findings);
110 | 
111 |             // Step 6 — mark COMPLETED
112 |             review.setStatus("COMPLETED");
113 |             review.setProgress(100);
114 |             reviewRepository.save(review);
115 | 
116 |             log.info("[ANALYSIS] Completed review {} — {} findings (rules: {})",
117 |                     reviewId, findings.size(), engine.registeredRuleIds());
118 | 
119 |             // Step 7 — emit notifications
120 |             notificationService.emit(
121 |                     EventType.REVIEW_COMPLETED,
122 |                     "Review completed: " + review.getTitle(),
123 |                     "Analysis finished for review #" + reviewId + ".",
124 |                     reviewId);
125 | 
126 |             if (!findings.isEmpty()) {
127 |                 String topSeverity = findings.stream()
128 |                         .map(Finding::getSeverity)
129 |                         .reduce((a, b) -> severityRank(a) >= severityRank(b) ? a : b)
130 |                         .orElse("low");
131 |                 notificationService.emit(
132 |                         EventType.NEW_FINDINGS,
133 |                         findings.size() + " finding" + (findings.size() == 1 ? "" : "s")
134 |                                 + " in \u201c" + review.getTitle() + "\u201d",
135 |                         findings.size() + " issue" + (findings.size() == 1 ? "" : "s")
136 |                                 + " detected (highest severity: " + topSeverity + ").",
137 |                         reviewId);
138 |             }
139 | 
140 |         } catch (Exception ex) {
141 |             log.error("[ANALYSIS] Analysis failed for review {}: {}", reviewId, ex.getMessage(), ex);
142 |             try {
143 |                 review.setStatus("FAILED");
144 |                 reviewRepository.save(review);
145 |             } catch (Exception saveEx) {
146 |                 log.error("[ANALYSIS] Could not persist FAILED status for review {}", reviewId, saveEx);
147 |             }
148 |         }
149 |     }
150 | 
151 |     // ── helpers ───────────────────────────────────────────────────────────────
152 | 
153 |     private static int severityRank(String s) {
154 |         return switch (s == null ? "" : s.toLowerCase()) {
155 |             case "critical" -> 4;
156 |             case "high"     -> 3;
157 |             case "medium"   -> 2;
158 |             case "low"      -> 1;
159 |             default         -> 0;
160 |         };
161 |     }
