20 | /**
21 |  * Generates meaningful, deterministic test scaffolds from static-analysis findings.
22 |  *
23 |  * <h3>How tests are generated</h3>
24 |  * <p>Each finding produced by the static-analysis engine carries a rule ID
25 |  * ({@code SQLI-001}, {@code CRED-001}, {@code EXEC-001}, {@code DESER-001})
26 |  * and an evidence snippet (the actual offending code).  {@link TestCodeGenerator}
27 |  * uses this information to produce a Java JUnit 5 test file that:
28 |  * <ul>
29 |  *   <li>References the exact file and line number of the finding.</li>
30 |  *   <li>Embeds the offending code as a comment.</li>
31 |  *   <li>Provides rule-specific scaffolding instructions and assertion stubs.</li>
32 |  *   <li>Calls {@code fail()} so the test fails fast if run without being completed —
33 |  *       preventing a false "green" result.</li>
34 |  * </ul>
35 |  *
36 |  * <h3>Execution status</h3>
37 |  * <p>All generated tests start as {@code NOT_RUN}.  Tests are <strong>never
38 |  * executed automatically</strong> by this service.  The status must only be
39 |  * changed to {@code PASSED} or {@code FAILED} after actual test execution.
40 |  * Do not mark a test as PASSED unless it was actually run and passed.
41 |  *
42 |  * <h3>No AI involved</h3>
43 |  * <p>Generation is 100% deterministic pattern-based templating — no IBM Granite,
44 |  * no watsonx, no external API call.
45 |  */
46 | @Service
47 | public class TestGenerationService {
48 | 
49 |     private static final Logger log = LoggerFactory.getLogger(TestGenerationService.class);
50 | 
51 |     private final ReviewRepository        reviewRepository;
52 |     private final FindingRepository       findingRepository;
53 |     private final GeneratedTestRepository testRepository;
54 |     private final NotificationService     notificationService;
55 | 
56 |     public TestGenerationService(ReviewRepository reviewRepository,
57 |                                  FindingRepository findingRepository,
58 |                                  GeneratedTestRepository testRepository,
59 |                                  NotificationService notificationService) {
60 |         this.reviewRepository    = reviewRepository;
61 |         this.findingRepository   = findingRepository;
62 |         this.testRepository      = testRepository;
63 |         this.notificationService = notificationService;
64 |     }
65 | 
66 |     // ── queries ───────────────────────────────────────────────────────────────
67 | 
68 |     public List<GeneratedTest> getTestsForReview(Long reviewId) {
69 |         getReviewOrThrow(reviewId);
70 |         return testRepository.findByReview_Id(reviewId);
71 |     }
72 | 
73 |     // ── generation ────────────────────────────────────────────────────────────
74 | 
75 |     /**
76 |      * Generate (or re-generate) test scaffolds from the findings of a
77 |      * {@code COMPLETED} review.
78 |      *
79 |      * <p>The operation is idempotent — any previously generated tests for this
80 |      * review are deleted before new ones are written.
81 |      *
82 |      * @param reviewId review to generate tests for
83 |      * @return list of persisted generated tests, each with status {@code NOT_RUN}
84 |      * @throws ResourceNotFoundException if the review does not exist
85 |      * @throws IllegalArgumentException  if the review is not yet {@code COMPLETED}
86 |      */
87 |     @Transactional
88 |     public List<GeneratedTest> generateTests(Long reviewId) {
89 |         Review review = getReviewOrThrow(reviewId);
90 | 
91 |         if (!"COMPLETED".equals(review.getStatus())) {
92 |             throw new IllegalArgumentException(
93 |                 "Tests can only be generated for COMPLETED reviews. Current status: "
94 |                 + review.getStatus());
95 |         }
96 | 
97 |         // Clear any previously generated tests (idempotent re-generation)
98 |         testRepository.deleteByReview_Id(reviewId);
99 | 
100 |         List<Finding> findings = findingRepository.findByReview_Id(reviewId);
101 |         List<GeneratedTest> tests = new ArrayList<>();
102 | 
103 |         for (Finding f : findings) {
104 |             GeneratedTest t = buildTestForFinding(review, f);
105 |             tests.add(t);
106 |         }
107 | 
108 |         // If there are no findings at all, add one honest coverage scaffold
109 |         if (findings.isEmpty()) {
110 |             tests.add(buildNoFindingsScaffold(review));
111 |         }
112 | 
113 |         List<GeneratedTest> saved = testRepository.saveAll(tests);
114 |         log.info("[TESTGEN] Generated {} test scaffold(s) for review {} (all status=NOT_RUN)",
115 |                  saved.size(), reviewId);
116 | 
117 |         notificationService.emit(
118 |                 EventType.TESTS_GENERATED,
119 |                 saved.size() + " test scaffold" + (saved.size() == 1 ? "" : "s") + " generated",
120 |                 saved.size() + " scaffold" + (saved.size() == 1 ? "" : "s")
121 |                         + " created for review #" + reviewId + " (status: NOT_RUN — not executed).",
122 |                 reviewId);
123 | 
124 |         return saved;
125 |     }
126 | 
127 |     // ── builders ──────────────────────────────────────────────────────────────
128 | 
129 |     private GeneratedTest buildTestForFinding(Review review, Finding f) {
130 |         String code     = TestCodeGenerator.generate(f);
131 |         String filePath = TestCodeGenerator.testFilePath(f);
132 |         String type     = TestCodeGenerator.testType(f);
133 |         String name     = buildTestName(f);
134 | 
135 |         GeneratedTest t = new GeneratedTest(
136 |             review,
137 |             name,
138 |             filePath,
139 |             "NOT_RUN",   // never executed automatically
140 |             null,        // duration unknown until actually run
141 |             String.valueOf(f.getId()),
142 |             code
143 |         );
144 |         t.setTestType(type);
145 |         return t;
146 |     }
147 | 
148 |     private GeneratedTest buildNoFindingsScaffold(Review review) {
149 |         String code =
150 |             "// ─────────────────────────────────────────────────────────────────────────\n" +
151 |             "// GENERATED BY ThirdEye static-analysis test generator\n" +
152 |             "// Status: NOT_RUN  (never executed)\n" +
153 |             "// No security findings were detected in this review.\n" +
154 |             "// ─────────────────────────────────────────────────────────────────────────\n\n" +
155 |             "import org.junit.jupiter.api.DisplayName;\n" +
156 |             "import org.junit.jupiter.api.Test;\n" +
157 |             "import static org.assertj.core.api.Assertions.assertThat;\n\n" +
158 |             "/**\n" +
159 |             " * Coverage scaffold for review #" + review.getId() + ".\n" +
160 |             " * No security findings were detected by the static analyser.\n" +
161 |             " * Add tests here to verify the expected behaviour of the reviewed code.\n" +
162 |             " */\n" +
163 |             "// SCAFFOLD — implement the body before using this test\n" +
164 |             "class Review" + review.getId() + "CoverageTest {\n\n" +
165 |             "    @Test\n" +
166 |             "    @DisplayName(\"Review #" + review.getId() + " — no security regressions\")\n" +
167 |             "    void reviewedCode_hasNoSecurityRegressions() {\n" +
168 |             "        // TODO: add assertions that the reviewed code behaves correctly.\n" +
169 |             "        // The static analyser found no issues, but functional tests\n" +
170 |             "        // should still cover the changed code paths.\n" +
171 |             "        fail(\"Test not yet implemented.\");\n" +
172 |             "    }\n" +
173 |             "}\n";
174 | 
175 |         GeneratedTest t = new GeneratedTest(
176 |             review,
177 |             "review #" + review.getId() + " — no security regressions scaffold",
178 |             "src/test/java/Review" + review.getId() + "CoverageTest.java",
179 |             "NOT_RUN",
180 |             null,
181 |             null,
182 |             code
183 |         );
184 |         t.setTestType("COVERAGE");
185 |         return t;
186 |     }
187 | 
188 |     // ── helpers ───────────────────────────────────────────────────────────────
189 | 
190 |     private String buildTestName(Finding f) {
191 |         String ruleId = TestCodeGenerator.testType(f);
192 |         String file   = f.getFile() == null ? "unknown" : f.getFile();
193 |         // Derive the short filename for readability
194 |         String shortFile = file.contains("/") ? file.substring(file.lastIndexOf('/') + 1) : file;
195 | 
196 |         return switch (ruleId) {
197 |             case "SQLI-001"  -> shortFile + ":" + f.getLine() +
198 |                                 " — SQL query must not concatenate user input";
199 |             case "CRED-001"  -> shortFile + ":" + f.getLine() +
200 |                                 " — credential must not be a hardcoded literal";
201 |             case "EXEC-001"  -> shortFile + ":" + f.getLine() +
202 |                                 " — command execution must reject shell-injection payloads";
203 |             case "DESER-001" -> shortFile + ":" + f.getLine() +
204 |                                 " — deserialization must reject untrusted class types";
205 |             default          -> shortFile + ":" + f.getLine() +
206 |                                 " — " + lowerFirst(f.getTitle());
207 |         };
208 |     }
209 | 
210 |     private String lowerFirst(String s) {
211 |         if (s == null || s.isEmpty()) return s;
212 |         return Character.toLowerCase(s.charAt(0)) + s.substring(1);
213 |     }
214 | 
215 |     private Review getReviewOrThrow(Long reviewId) {
216 |         return reviewRepository.findById(reviewId)
217 |                 .orElseThrow(() -> new ResourceNotFoundException(
218 |                         "Review not found with id: " + reviewId));
219 |     }
220 | }
