          <span className="font-serif text-lg font-semibold tracking-tight whitespace-nowrap">
            ThirdEye AI
          </span>
        )}
      </div>

      <nav className="flex flex-1 flex-col gap-1 px-3">
        {navItems.map(({ to, label, icon: Icon }) => (
          <NavLink
            key={to}
            to={to}
