              `group flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm transition-colors ${
                isActive
                  ? 'bg-white/10 text-white font-medium'
                  : 'text-ivory-100/65 hover:bg-white/5 hover:text-ivory-100'
              }`
            }
            title={collapsed ? label : undefined}
